command:
set -euo pipefail
test "$(hostname)" = "ai-core-node-projekt-frankenstein"
echo ===SUBJECT===
sha256sum buehne.html buehne_daemon.py filmlook.js
echo ===SERVICE===
systemctl --user is-active frankenstein-buehne.service
curl -fsS http://127.0.0.1:8788/ >/dev/null
echo ===RELIEF2_REFERENCES===
grep -n -E 'augen_blink_relief2|eye_identity|BLINK_BILDER|_sonderLaeuft.*pupillen|pupillen-glow.*opacity|blinzelPhase|function blinzeln' buehne.html | head -160
echo ===RELIEF2_FILES===
if test -d augen_blink_relief2; then find augen_blink_relief2 -maxdepth 1 -type f -name '*.png' -print0 | sort -z | xargs -0 sha256sum; else echo NO_RELIEF2_DIR; fi
echo ===RAW_FILES===
sha256sum augen_blink/blink_000.png augen_blink/blink_006.png augen_gaze/rotglow_tracking_master.png
echo ===FPS===
for i in $(seq 0 4); do curl -fsS http://127.0.0.1:8788/api/status | python3 -c 'import json,sys;d=json.load(sys.stdin);print((d.get("fps") or {}).get("fps"))'; sleep .1; done
echo SCOPE=READ_ONLY_CURRENT_RELIEF2_SUBJECT_BINDING
